import { usePrefix } from "../../internal/usePrefix.js";
import { GridSettings } from "./GridContext.js";
import React from "react";
import cx from "classnames";
import PropTypes from "prop-types";
import { jsx } from "react/jsx-runtime";
//#region src/components/Grid/FlexGrid.tsx
/**
* Copyright IBM Corp. 2016, 2026
*
* This source code is licensed under the Apache-2.0 license found in the
* LICENSE file in the root directory of this source tree.
*/
const FlexGrid = React.forwardRef(({ as, condensed = false, narrow = false, fullWidth = false, withRowGap = false, className: containerClassName, children, ...rest }, ref) => {
	const prefix = usePrefix();
	const className = cx(containerClassName, {
		[`${prefix}--grid`]: true,
		[`${prefix}--grid--condensed`]: condensed,
		[`${prefix}--grid--narrow`]: narrow,
		[`${prefix}--grid--full-width`]: fullWidth,
		[`${prefix}--grid--with-row-gap`]: withRowGap
	});
	return /* @__PURE__ */ jsx(GridSettings, {
		mode: "flexbox",
		subgrid: false,
		children: /* @__PURE__ */ jsx(as || "div", {
			className,
			ref,
			...rest,
			children
		})
	});
});
FlexGrid.displayName = "FlexGrid";
FlexGrid.propTypes = {
	/**
	* Provide a custom element to render instead of the default <div>
	*/
	as: PropTypes.oneOfType([PropTypes.string, PropTypes.elementType]),
	/**
	* Pass in content that will be rendered within the `FlexGrid`
	*/
	children: PropTypes.node,
	/**
	* Specify a custom className to be applied to the `FlexGrid`
	*/
	className: PropTypes.string,
	/**
	* Collapse the gutter to 1px. Useful for fluid layouts.
	* Rows have 1px of margin between them to match gutter.
	*/
	condensed: PropTypes.bool,
	/**
	* Remove the default max width that the grid has set
	*/
	fullWidth: PropTypes.bool,
	/**
	* Container hangs 16px into the gutter. Useful for
	* typographic alignment with and without containers.
	*/
	narrow: PropTypes.bool,
	/**
	* Add a row gap to the grid that matches the current gutter size.
	* This is useful when you want consistent vertical spacing between rows.
	*/
	withRowGap: PropTypes.bool
};
const FlexGridComponent = FlexGrid;
//#endregion
export { FlexGridComponent as FlexGrid };
